import{_ as e,H as p,f as t,i as a}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"15-配置中心在微服务中发挥着怎样的作用？","description":"","frontmatter":{},"headers":[{"level":2,"title":"传统配置管理的弊端","slug":"传统配置管理的弊端","link":"#传统配置管理的弊端","children":[]},{"level":2,"title":"分布式配置中心","slug":"分布式配置中心","link":"#分布式配置中心","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SpringCloud微服务项目实战/15-配置中心在微服务中发挥着怎样的作用？.md","filePath":"SpringCloud微服务项目实战/15-配置中心在微服务中发挥着怎样的作用？.md","lastUpdated":1795535212000}'),i={name:"SpringCloud微服务项目实战/15-配置中心在微服务中发挥着怎样的作用？.md"};function A(n,E,o,s,l,r){return p(),t("div",null,[...E[0]||(E[0]=[a('<h1 id="_15-配置中心在微服务中发挥着怎样的作用" tabindex="-1">15-配置中心在微服务中发挥着怎样的作用？ <a class="header-anchor" href="#_15-配置中心在微服务中发挥着怎样的作用" aria-label="Permalink to &quot;15-配置中心在微服务中发挥着怎样的作用？&quot;">​</a></h1><p>你好，我是姚秋辰。</p><p>在微服务架构中，我们会使用一个分布式的“配置中心”来管理所有的配置文件和配置项。相比于传统的基于文件的配置管理方式，配置中心有什么独特的功能和优势呢？今天这节课，我就带你了解 Nacos 配置中心的特性，以及这些特性在微服务体系中所发挥的作用。</p><p>在 Spring Boot 应用中，我们习惯于使用传统的配置管理方式，将各种配置项都维护在application.yml 或 application.properties 文件中。从完成业务逻辑的角度来看，这样做是没问题的。但在微服务架构中，我们可以采取一种更“优雅”的方式组织配置文件，实现高效灵活的配置管理。</p><p>我要先带你回想一下传统的配置管理途径都有哪些，这些途径在使用上有哪些弊端。然后，我们再来了解微服务架构下的“配置中心”是如何解决这些问题的。</p><h2 id="传统配置管理的弊端" tabindex="-1">传统配置管理的弊端 <a class="header-anchor" href="#传统配置管理的弊端" aria-label="Permalink to &quot;传统配置管理的弊端&quot;">​</a></h2><p>我们通常可以采用四种途径在程序中指定配置项，它们分别是硬编码、配置文件、环境 / 启动变量、数据库动态获取，我们先来了解一下这四种配置管理方式是如何实现的。</p><ul><li><p>硬编码：最简单粗暴的方式，在 Bean 初始化的上下文中，直接通过在代码中 hardcode 的方式指定配置信息；</p></li><li><p>配置文件：使用 application 和 bootstrap 配置文件来设置配置项，这是目前比较“优雅”常用的方式；</p></li><li><p>环境 / 启动变量：通过操作系统的环境变量，或者启动命令中的 -D 参数传入配置项；</p></li><li><p>数据库 / 缓存动态获取：将配置项保存在数据库里，每次执行一个 select 语句实现动态查询。</p></li></ul><p>看似我们有了不少办法来实现配置管理，但实际上，以上的几种途径或多或少都有一些弊端。</p><p>从职责分离的角度来讲，硬编码无法将“业务逻辑”与“配置管理”拆分开来。尽管硬编码实现起来最为简单，它仍然是我最不推荐的一种方式。</p><p>从灵活性的角度来讲，无论你用的是硬编码、配置文件还是环境 / 启动变量的方式，只要你需要对配置项进行变更，你就必须对代码 / 启动命令进行修改，然后重新打包并部署应用，无法做到在运行期灵活变更配置项。</p><p>数据库 / 缓存动态获取的方式和上面几种相比，具备了一定的灵活性。但从版本控制的角度来看，配置项也是一种“代码资源”，采用数据库 / 缓存控制并不能很好地实现配置版本的控制和历史版本回滚。而面对高并发场景时，如果我们采用数据库方案，还要时刻关注 DB 的性能指标，以免被流量打崩。</p><p>除此以外，多格式支持和安全性也是需要考虑的因素。对于用户名密码之类的敏感数据，如果明目张胆地放在代码库中，那么将显著增加“删库跑路”事件的发生几率。</p><p>到这里你会发现，传统的配置管理方式或多或少都存在着一些弊端。你也可能会问，分布式配置中心可以解决这些问题吗？答案是当然。接下来，我就带你了解分布式配置中心有哪些具体的作用。</p><h2 id="分布式配置中心" tabindex="-1">分布式配置中心 <a class="header-anchor" href="#分布式配置中心" aria-label="Permalink to &quot;分布式配置中心&quot;">​</a></h2><p>在微服务的架构体系中，我们会使用一个中心化的分布式配置中心作为配置文件的管理者。</p><p>在应用程序端，我们只将一些必要的配置项添加到配置文件中（如 application.yml 和bootstrap.yml），而大部分的配置项都被保存在配置中心集群里。客户端在启动的时候从配置中心获取所有的配置项，用于各个组件的初始化。</p><p>我以下节课将要学习的 Nacos Config 为例，画了一张架构图来帮你理解这个过程，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/1.png" alt=""></a></p><p>从上面的图中，你可以看到分布式配置中心在配置管理方面发挥的作用，接下来我就为你展开讲一讲。</p><p>高可用性：微服务组件的高可用性是首要目标。配置中心并不是一个中心化的单点应用，而是一个通过集群对外提供服务的组件。在一致性算法的基础上，集群中各个节点之间会互相同步配置数据，或者从统一数据源读取配置数据。即便个别节点挂掉，也不影响整个集群的可用性；</p><p>环境隔离特性：Nacos 支持通过 Namespace 属性指定当前配置项所在的环境，你可以为自己的应用系统创建开发环境、预发环境和生产环境，不同环境之间的配置文件是相互隔离的；</p><p>多格式支持：Nacos 支持多种不同格式的配置内容，你可以使用纯文本、JSON、XML、YAML 和 Properties 多种文件后缀；</p><p>访问控制：Nacos 实现了权限管理功能，你可以在控制台创建用户账号和权限组，限制某个账号可以访问哪些命名空间，并配置账号的读写权限（只读、只写、读写）。通过这种方式，你可以保障敏感信息（如数据库用户名和密码）的安全；</p><p>职责分离：配置项从 jar 包中抽离了出来，修改配置项再也不需要重新编译打包应用程序了，完美实现了配置项管理与业务代码之间的职责分离；</p><p>版本控制和审计功能：配置项也是一种代码，而且配置 bug 往往比代码中的 bug 造成的影响更大。因此，在微服务架构中我们需要确保配置中心具备完善的版本控制和审计功能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/2.png" alt=""></a></p><p>从图中你可以看出，通过 Nacos 的“历史版本”功能，你可以查看任何一个配置文件的历史修改记录，包括改动的时间和操作人。针对每一个改动记录，我们可以查看这一版本的配置详情，或者做线上配置项的回滚操作。</p><p>除了上面我们提到的功能以外，Nacos 还可以支持多文件源读取以及运行期配置变更。尤其是动态变更推送，更是微服务架构下不可或缺的配置管理能力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/15-%25E9%2585%258D%25E7%25BD%25AE%25E4%25B8%25AD%25E5%25BF%2583%25E5%259C%25A8%25E5%25BE%25AE%25E6%259C%258D%25E5%258A%25A1%25E4%25B8%25AD%25E5%258F%2591%25E6%258C%25A5%25E7%259D%2580%25E6%2580%258E%25E6%25A0%25B7%25E7%259A%2584%25E4%25BD%259C%25E7%2594%25A8%25EF%25BC%259F/3.png" alt=""></a></p><p>Nacos 具备很高的灵活性，你可以在项目中指定从多个 Nacos 配置文件中获取信息，这些文件可以是不同名称、不同格式的配置文件。这个特性允许你对配置文件做更细致的“职责隔离”。比如你可以把 Redis 连接信息做成一个独立的配置文件，让集群中的所有应用消费同一个文件来初始化 Redis Connection。</p><p>当配置项发生变化的时候，服务端可以通过监听变更事件的方式，从 Nacos 服务器获取到最新的配置信息。这个功能就是配置项动态更新，它可以让你在不重启应用程序的前提下更新配置信息，这在微服务系统中大有用途。</p><p>我来列举几个配置项动态更新的使用场景，帮助你理解它的作用。</p><p>业务开关</p><p>动态配置的一个作用是通过业务开关控制功能的开启 / 关闭。比如在做主链路规划的时候，我们经常需要在一些非关键服务上预留一个“人工降级”开关，在业务运行期对特定业务做定向熔断。</p><p>对于一些大需求点的功能更新，经常涉及到上下游多个微服务的改动，但每个微服务的上线时间往往是不一样的。这时候我们就可以在代码中预留一个“业务开关”，在当前服务上线之初，开关处于关闭状态，待所有上下游服务都完成了上线之后，再通过开关开启新功能。如果出现异常情况，还可以通过这个功能开关切换回老的执行逻辑。</p><p>业务规则更新</p><p>对于一些更新比较频繁的业务数据，我们可以把这部分数据放到配置中心中。比如说我在搭建新零售平台的商品中心的时候，会将一些运营文案信息部署到配置中心。这样一来，我们就可以根据运营活动随时更新资源位的布局、样式以及展位商品。</p><p>灰度发布验证</p><p>如果你即将发布新的配置项变更，但是在应用到整个集群之前你想先挑几台服务器测试一下，那么你可以使用 Nacos 的 Beta 发布功能，将配置项定向推送到特定 IP 地址的 Client 机器，完成线上测试。利用 Beta 发布 + 业务开关的组合，你还可以在线上定向开启特定 IP 服务器的业务开关，实现轻量级的灰度测试。</p><p>到这里，相信你已经对配置中心在微服务中的应用场景有了比较全面的认识。现在，我们来回顾一下这节课的重点内容。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们了解了配置中心在微服务架构下的使用场景。对于开发人员来说，“动态属性推送”应该是我们在工作中最常用到的功能点了，尤其在拥抱变化的互联网公司更是如此。因为互联网行业的需求变动非常频繁，如何巧妙地利用配置中心的动态推送功能，将“变化的需求部分”和“不变的代码部分”隔离开来，是开发业务场景时需要着重考虑的。</p><p>我来举一个例子，很多电商 APP 上都有商品资源位，根据各种活动场景的不同，这些资源位的样式和排版都会根据运营要求发生变化。大多数开发人员可能会以为这些页面排版和背景图之类的活动页面是通过代码写死的，其实不然。面对玩法花样多变的运营场景，我们会把资源位抽象成不同的模板，将模板添加到配置中心里，客户端程序根据不同模板做布局适配即可。这样一来，不管是 618、双 11 还是双 12，只需要更改配置中心的模板内容就可以更改 APP端页面布局，省去了重新发版的工作。（当然了，APP 端要基于 H5 构建，不能基于Native）。</p><p>在下节课里，我将带你集成应用程序到 Nacos 配置中心，并实现属性动态推送的场景。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过这节课的学习，你能想一下动态属性推送还有哪些应用场景吗？如果你的项目也使用了动态推送功能，欢迎你在评论区将你的业务场景分享出来。</p><p>好啦，这节课就结束啦。欢迎你把这节课分享给更多对 Spring Cloud 感兴趣的朋友。我是姚秋辰，我们下节课再见！</p>',48)])])}const h=e(i,[["render",A]]);export{c as __pageData,h as default};
